using System;using System.IO;using System.Threading;using System.Threading.Tasks;
class ResumeTest {static int Main(string[] args){string source=args[0],part=args[1];using(var input=File.OpenRead(source))using(var output=File.Create(part)){byte[] buffer=new byte[1048576];long left=RemoteGame.ArchiveSize-1048576;while(left>0){int n=input.Read(buffer,0,(int)Math.Min(left,buffer.Length));output.Write(buffer,0,n);left-=n;}}
 GameInstall.Pause(true);bool finished=false;var task=Task.Run(()=>{RemoteGame.Download(part,(n,s)=>Console.WriteLine(s));finished=true;});Thread.Sleep(1000);if(finished)throw new Exception("Download ignored pause");GameInstall.Pause(false);task.GetAwaiter().GetResult();if(Launcher.Hash(part)!=RemoteGame.ArchiveHash)throw new Exception("Resumed archive hash mismatch");Console.WriteLine("PASS Google Drive confirmation, paused download, resume existing partial, archive SHA-256");return 0;}}
